mapper.select:
SELECT COUNT(*) > 0
FROM dish d
JOIN shop s ON s.id = d.shop_id
WHERE d.id = #{dishId}
  AND d.shop_id = #{shopId}
  AND s.region = #{region}
  AND s.status = 1
  AND s.is_deleted = FALSE

SELECT id, region, shop_id, dish_id, user_id, score, content, created_at
FROM dish_review
WHERE shop_id = #{shopId}
  AND dish_id = #{dishId}
  AND region = #{region}
  AND is_deleted = FALSE
ORDER BY id DESC
